/**
 * @brief Test context for spec:/c/time/req/timegm test case.
 */
typedef struct {
  /**
   * @brief This member specifies the state of the member tm_sec.
   */
  MemberState second;

  /**
   * @brief This member specifies the state of the member tm_min.
   */
  MemberState minute;

  /**
   * @brief This member specifies the state of the member tm_hour.
   */
  MemberState hour;

  /**
   * @brief This member specifies the state of the member tm_mday.
   */
  MemberState month_day;

  /**
   * @brief This member specifies the state of the member tm_mon.
   */
  MemberState month;

  /**
   * @brief This member contains the last day of the month which tm_year and
   *   tm_mon specify.
   */
  int64_t last_day;

  /**
   * @brief This member specifies the leap year class.
   */
  LeapYear leap_year;

  /**
   * @brief This member contains the broken-down time of the function call.
   */
  struct tm tm;

  /**
   * @brief This member contains the broken-down time which the call shall
   *   produce.
   */
  struct tm expected;

  /**
   * @brief This member contains the time which the call shall return.
   */
  time_t time;

  /**
   * @brief This member contains the return value of the function call.
   */
  time_t result;

  struct {
    /**
     * @brief This member defines the pre-condition states for the next action.
     */
    size_t pcs[ 6 ];

    /**
     * @brief If this member is true, then the test action loop is executed.
     */
    bool in_action_loop;

    /**
     * @brief This member contains the next transition map index.
     */
    size_t index;

    /**
     * @brief This member contains the current transition map entry.
     */
    CTimeReqTimegm_Entry entry;

    /**
     * @brief If this member is true, then the current transition variant
     *   should be skipped.
     */
    bool skip;
  } Map;
} CTimeReqTimegm_Context;

