typedef CTimeReqTimegm_Context Context;

#define WDAY_SENTINEL 7

static const int64_t years[ 4 ] = { 2023, 2024, 2100, 2000 };

static int GetValue(
  MemberState state,
  int         first,
  int         last,
  int         between,
  int         above
)
{
  switch ( state ) {
    case STATE_MIN:
      return INT_MIN;
    case STATE_NEGATIVE:
      return first - 40;
    case STATE_FIRST:
      return first;
    case STATE_BETWEEN:
      return between;
    case STATE_LAST:
      return last;
    case STATE_ABOVE:
      return above;
    default:
      return INT_MAX;
  }
}

static int64_t FloorDivide( int64_t a, int64_t b )
{
  int64_t q;

  q = a / b;

  if ( ( a % b ) != 0 && ( ( a < 0 ) != ( b < 0 ) ) ) {
    --q;
  }

  return q;
}

/*
 * The expected time counts each member in its unit from the first day of the
 * month which the members tm_year and tm_mon specify.
 */
static void GetExpected( Context *ctx )
{
  int64_t months;
  int64_t year;
  int64_t month;
  int64_t days;

  months = (int64_t) ctx->tm.tm_year * 12 + ctx->tm.tm_mon;
  year = FloorDivide( months, 12 ) + 1900;
  month = months - FloorDivide( months, 12 ) * 12 + 1;
  days = DaysFromCivil( year, (unsigned int) month, 1 ) + ctx->tm.tm_mday - 1;
  ctx->time = (time_t) ( days * 86400 + (int64_t) ctx->tm.tm_hour * 3600 +
                         (int64_t) ctx->tm.tm_min * 60 + ctx->tm.tm_sec );
  memset( &ctx->expected, 0, sizeof( ctx->expected ) );
  (void) gmtime_r( &ctx->time, &ctx->expected );
}

static int64_t GetLastDayOfMonth( int64_t year, int64_t month )
{
  if ( month == 12 ) {
    return 31;
  }

  return DaysFromCivil( year, (unsigned int) month + 1, 1 ) -
         DaysFromCivil( year, (unsigned int) month, 1 );
}

static void Normalize( Context *ctx )
{
  int64_t months;
  int64_t year;
  int64_t month;

  months = (int64_t) ctx->tm.tm_year * 12 + ctx->tm.tm_mon;
  year = FloorDivide( months, 12 ) + 1900;
  month = months - FloorDivide( months, 12 ) * 12 + 1;
  ctx->last_day = GetLastDayOfMonth( year, month );
}

static void CTimeReqTimegm_Pre_Second_Prepare(
  CTimeReqTimegm_Context   *ctx,
  CTimeReqTimegm_Pre_Second state
)
{
  switch ( state ) {
    case CTimeReqTimegm_Pre_Second_Min: {
      /*
       * While the member tm_sec of the object referenced by the `timeptr`
       * parameter is the least value of type int.
       */
      ctx->second = STATE_MIN;
      break;
    }

    case CTimeReqTimegm_Pre_Second_Negative: {
      /*
       * While the member tm_sec of the object referenced by the `timeptr`
       * parameter is greater than the least value of type int and less than
       * zero.
       */
      ctx->second = STATE_NEGATIVE;
      break;
    }

    case CTimeReqTimegm_Pre_Second_First: {
      /*
       * While the member tm_sec of the object referenced by the `timeptr`
       * parameter is zero.
       */
      ctx->second = STATE_FIRST;
      break;
    }

    case CTimeReqTimegm_Pre_Second_Between: {
      /*
       * While the member tm_sec of the object referenced by the `timeptr`
       * parameter is greater than zero and less than 59.
       */
      ctx->second = STATE_BETWEEN;
      break;
    }

    case CTimeReqTimegm_Pre_Second_Last: {
      /*
       * While the member tm_sec of the object referenced by the `timeptr`
       * parameter is 59.
       */
      ctx->second = STATE_LAST;
      break;
    }

    case CTimeReqTimegm_Pre_Second_Above: {
      /*
       * While the member tm_sec of the object referenced by the `timeptr`
       * parameter is greater than 59 and less than the greatest value of type
       * int.
       */
      ctx->second = STATE_ABOVE;
      break;
    }

    case CTimeReqTimegm_Pre_Second_Max: {
      /*
       * While the member tm_sec of the object referenced by the `timeptr`
       * parameter is the greatest value of type int.
       */
      ctx->second = STATE_MAX;
      break;
    }

    case CTimeReqTimegm_Pre_Second_NA:
      break;
  }
}

