static void CTimeReqTimegm_Pre_MonthDay_Prepare(
  CTimeReqTimegm_Context     *ctx,
  CTimeReqTimegm_Pre_MonthDay state
)
{
  switch ( state ) {
    case CTimeReqTimegm_Pre_MonthDay_Min: {
      /*
       * While the member tm_mday of the object referenced by the `timeptr`
       * parameter is the least value of type int.
       */
      ctx->month_day = STATE_MIN;
      break;
    }

    case CTimeReqTimegm_Pre_MonthDay_Negative: {
      /*
       * While the member tm_mday of the object referenced by the `timeptr`
       * parameter is greater than the least value of type int and less than
       * one.
       */
      ctx->month_day = STATE_NEGATIVE;
      break;
    }

    case CTimeReqTimegm_Pre_MonthDay_First: {
      /*
       * While the member tm_mday of the object referenced by the `timeptr`
       * parameter is one.
       */
      ctx->month_day = STATE_FIRST;
      break;
    }

    case CTimeReqTimegm_Pre_MonthDay_Between: {
      /*
       * While the member tm_mday of the object referenced by the `timeptr`
       * parameter is greater than one and less than the last day of the month.
       */
      ctx->month_day = STATE_BETWEEN;
      break;
    }

    case CTimeReqTimegm_Pre_MonthDay_Last: {
      /*
       * While the member tm_mday of the object referenced by the `timeptr`
       * parameter is the last day of the month.
       */
      ctx->month_day = STATE_LAST;
      break;
    }

    case CTimeReqTimegm_Pre_MonthDay_Above: {
      /*
       * While the member tm_mday of the object referenced by the `timeptr`
       * parameter is greater than the last day of the month and less than the
       * greatest value of type int.
       */
      ctx->month_day = STATE_ABOVE;
      break;
    }

    case CTimeReqTimegm_Pre_MonthDay_Max: {
      /*
       * While the member tm_mday of the object referenced by the `timeptr`
       * parameter is the greatest value of type int.
       */
      ctx->month_day = STATE_MAX;
      break;
    }

    case CTimeReqTimegm_Pre_MonthDay_NA:
      break;
  }
}

