static void CTimeReqTimegm_Post_Zone_Check(
  CTimeReqTimegm_Context  *ctx,
  CTimeReqTimegm_Post_Zone state
)
{
  switch ( state ) {
    case CTimeReqTimegm_Post_Zone_Set: {
      /*
       * The member tm_zone of the object referenced by the `timeptr` parameter
       * shall reference the string UTC.
       */
      T_assert_not_null( ctx->tm.tm_zone );
      T_eq_str( ctx->tm.tm_zone, "UTC" );
      break;
    }

    case CTimeReqTimegm_Post_Zone_NA:
      break;
  }
}

static void CTimeReqTimegm_Action( CTimeReqTimegm_Context *ctx )
{
  ctx->tm.tm_year = (int) ( years[ ctx->leap_year ] - 1900 );
  ctx->tm.tm_mon = GetValue( ctx->month, 0, 11, 1, 13 );
  Normalize( ctx );
  ctx->tm.tm_mday = GetValue(
    ctx->month_day,
    1,
    (int) ctx->last_day,
    15,
    (int) ctx->last_day + 40
  );
  ctx->tm.tm_hour = GetValue( ctx->hour, 0, 23, 12, 25 );
  ctx->tm.tm_min = GetValue( ctx->minute, 0, 59, 30, 61 );
  ctx->tm.tm_sec = GetValue( ctx->second, 0, 59, 30, 61 );
  ctx->tm.tm_wday = WDAY_SENTINEL;
  ctx->tm.tm_yday = -1;
  ctx->tm.tm_isdst = 0;
  ctx->tm.tm_gmtoff = -1;
  ctx->tm.tm_zone = NULL;
  GetExpected( ctx );
  ctx->result = timegm( &ctx->tm );
}

